@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=written name="Traffic flow by avenue and hour"
@r2 w.request.request act=change mood=do words="do the arrows large on the traffic flow chart" predicate=do
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=written family_words=chart name="traffic flow chart"
@r2.u1 w.request.unread request=$r2 text="arrows large" note=chart.flow.arrow.size value=large
@r3 w.request.request act=change mood=do words="show grid lines" predicate=show
@r3.t w.request.target request=$r3 family=chart mode=existing determiner=definite fill=context
@r3.l1 w.request.lookup request=$r3 target=$r3.t key=thing from=page
@r3.c1 w.request.constraint request=$r3 on=attribute attribute=chart.grid value=show operator=eq phase=result key_words=grid key_words="grid lines"

@r1 w.request.request act=change mood=do words="arrow style curved on the traffic flow chart"
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=written family_words=chart name="traffic flow chart"
@r1.u1 w.request.unread request=$r1 text="arrow style curved" note=chart.flow.arrow.style value=curved
@r2 w.request.request act=change mood=do words="do the arrows large on the traffic flow chart" predicate=do
@r2.t w.request.target request=$r2 family=chart mode=existing determiner=definite fill=written family_words=chart name="traffic flow chart"
@r2.u1 w.request.unread request=$r2 text="arrows large" note=chart.flow.arrow.size value=large
@r3 w.request.request act=change mood=do words="font bigger"
@r3.t w.request.target request=$r3 family=chart mode=existing determiner=definite fill=context
@r3.l1 w.request.lookup request=$r3 target=$r3.t key=thing from=page
@r3.c1 w.request.constraint request=$r3 on=attribute attribute=chart.fontSize words=bigger operator=delta phase=result step=more key_words=font
@f1 w.request.filler text="the missing piece"
